      const serie = d.rows.filter(r =&gt; s.sinGeo || r.codigo_territorio === T).sort((a, b) =&gt; a.fecha - b.fecha);
      if (!serie.length) return `${s.nombre}: [sin datos para ${nombreT} en Eurostat]`;
