${rubricaI.map(r =&gt; `&lt;tr&gt;&lt;td&gt;&lt;b&gt;${esc(r[0])}&lt;/b&gt;&lt;/td&gt;&lt;td&gt;${String(r[1]).replace(".", ",")}&lt;/td&gt;${r.slice(2).map(x =&gt; `&lt;td&gt;${esc(x)}&lt;/td&gt;`).join("")}&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;`).join("")}
&lt;tr&gt;&lt;td&gt;&lt;b&gt;Total&lt;/b&gt;&lt;/td&gt;&lt;td&gt;&lt;b&gt;10&lt;/b&gt;&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/body&gt;&lt;/html&gt;`;
