        const L = v.map((f, i) =&gt; f.map((x, j) =&gt; Math.max(...v.map(g =&gt; g[j])) - x)), sav = L.map(f =&gt; Math.max(...f));
        if (unico(lap) && unico(wal) && unico(hur) && unico(sav, false) && new Set([elige(lap), elige(wal), elige(hur), elige(sav, false)]).size &gt;= 2) break;
