  }
  const nuevaSala = () =&gt; Array.from(crypto.getRandomValues(new Uint8Array(8)), b =&gt; "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"[b % 32]).join("");
  const segundos = (ms) =&gt; ms == null ? "–" : `${(ms / 1000).toFixed(1).replace(".", ",")} s`;
