  function sortear(productos, n, desde, ultimo, azar = Math.random) {
    const out = [], bolsa = [];
    const [ua, um] = ultimo.split("-").map(Number), fin = ua * 12 + um - 1 - 12, ini = desde * 12;
    for (let i = 0; i &lt; n; i++) {
