    const r = await primera([["demo_gind", `&geo=${g}${desde(y0)}` + [...comps.map(c =&gt; c[0]), "GROWRT"].map(c =&gt; `&indic_de=${c}`).join("")]]);
    if (!r) return {error: "No se han podido cargar los datos de población de Eurostat."};
