    }
    return {comps: comps.map(c =&gt; ({k: c[1], color: c[2]})), filas, total, totalLabel: "Pernoctaciones en hoteles (tasa interanual, %)", unidad: "puntos porcentuales", fuente: "Eurostat (tour_occ_nim)",
      nota: "Contribución = variación interanual de las pernoctaciones de cada grupo dividida entre el total de pernoctaciones de hace un año."};
  }
