medidas = (o) =&gt; {
  const W = d3.sum(o, x =&gt; x.w), mu = d3.sum(o, x =&gt; x.v * x.w) / W;
  let acW = 0, acY = 0, g = 0; const lor = [{p: 0, l: 0}];
