      &lt;p class="juego-ind"&gt;Caso ${i + 1} de ${casos.length} · ${c.tema}&lt;/p&gt;
      &lt;p class="juego-p"&gt;${c.contexto}&lt;/p&gt;
      &lt;div class="engano-par"&gt;&lt;figure&gt;&lt;figcaption&gt;Gráfico A&lt;/figcaption&gt;${A}&lt;/figure&gt;&lt;figure&gt;&lt;figcaption&gt;Gráfico B&lt;/figcaption&gt;${B}&lt;/figure&gt;&lt;/div&gt;
      &lt;div class="engano-q1"&gt;&lt;p&gt;&lt;b&gt;1. ¿Qué gráfico engaña?&lt;/b&gt;&lt;/p&gt;&lt;div class="juego-ops"&gt;&lt;/div&gt;&lt;/div&gt;
      &lt;div class="engano-q2" hidden&gt;&lt;p&gt;&lt;b&gt;2. ¿Qué truco usa?&lt;/b&gt;&lt;/p&gt;&lt;div class="juego-ops juego-ops-v"&gt;&lt;/div&gt;&lt;/div&gt;
      &lt;div class="engano-sol" hidden&gt;&lt;/div&gt;
    &lt;/div&gt;`;
    const q1 = caja.querySelector(".engano-q1 .juego-ops"), q2 = caja.querySelector(".engano-q2"), sol = caja.querySelector(".engano-sol");
    const opciones = d3.shuffle([c.id, ...d3.shuffle(claves.filter(k =&gt; k !== c.id)).slice(0, 3)]);
    let bien1 = false;
    ["Gráfico A", "Gráfico B"].forEach((t, k) =&gt; {
      const b = html`&lt;button class="juego-op"&gt;${t}&lt;/button&gt;`;
      b.onclick = () =&gt; {
        const correcta = engA ? 0 : 1;
        bien1 = k === correcta; if (bien1) puntos++;
        q1.querySelectorAll("button").forEach((x, j) =&gt; { x.disabled = true; if (j === correcta) x.classList.add("ok"); });
        if (!bien1) b.classList.add("ko");
        q2.hidden = false; pintarMarcador();
      };
      q1.append(b);
    });
    const ops2 = q2.querySelector(".juego-ops");
    opciones.forEach(k =&gt; {
      const b = html`&lt;button class="juego-op"&gt;${ENG.trucos[k]}&lt;/button&gt;`;
      b.onclick = () =&gt; {
        const bien2 = k === c.id; if (bien2) puntos++;
        respondidos++;
        ops2.querySelectorAll("button").forEach((x, j) =&gt; { x.disabled = true; if (opciones[j] === c.id) x.classList.add("ok"); });
        if (!bien2) b.classList.add("ko");
        const total = (bien1 ? 1 : 0) + (bien2 ? 1 : 0);
        sol.innerHTML = `&lt;p class="juego-res ${total === 2 ? "bien" : "mal"}"&gt;${total === 2 ? "✅ ¡Bien visto!" : total === 1 ? "🟡 Casi." : "❌ Esta vez te han engañado."} El gráfico engañoso era el &lt;b&gt;${engA ? "A" : "B"}&lt;/b&gt; y el truco: &lt;b&gt;${ENG.trucos[c.id].toLowerCase()}&lt;/b&gt;.&lt;/p&gt;
          &lt;p&gt;${c.explicacion}&lt;/p&gt;&lt;p class="engano-regla"&gt;&lt;b&gt;Regla para no caer:&lt;/b&gt; ${c.regla}&lt;/p&gt;`;
        sol.hidden = false; pintarMarcador();
        window.cceeEvento && window.cceeEvento(`engano/${c.id}/${total}`, "Detecta el engaño", true);
      };
      ops2.append(b);
    });
    cont.append(caja);
  });
  pintarMarcador();
  return html`&lt;div&gt;${marcador}${cont}&lt;p class="nota"&gt;Fuente de los datos: Eurostat (tablas une_rt_m, gov_10dd_edpt1, nama_10_gdp, nama_10_pc, earn_mw_cur, prc_hicp_aind y sts_inpr_m), descargados en directo. Si algún caso no aparece, es que Eurostat no ha devuelto sus datos en este momento.&lt;/p&gt;&lt;/div&gt;`;
}

