        respuesta: sol, tol: 0.051, unidadResp: "puntos", solucion: `${fmt(ref.valor)} − ${fmt(h.valor)} = ${fmt(sol)} puntos. Al ser un porcentaje o un saldo, la variación se expresa en puntos.`};
