      respuesta: sol, tol: Math.max(0.11, Math.abs(sol) * 0.005), unidadResp: "%", solucion: `(${fmt(ref.valor)} / ${fmt(h.valor)} − 1) × 100 = ${fmt(sol)} %.`};
