      opciones: ops.map(r =&gt; r.territorio), respuesta: ops.indexOf(c),
      solucion: ops.slice().sort((a, b) =&gt; b.valor - a.valor).map(r =&gt; `${r.territorio}: ${fmt(r.valor)}`).join(" · ") + ` (${s.unidad}).`};
  }
