        opciones: ["Verdadero", "Falso"], respuesta: ok ? 0 : 1, solucion: `${h.periodo}: ${fmt(h.valor)} · ${u.periodo}: ${fmt(u.valor)}. Es ${ok ? "verdadero" : "falso"}.`};
