      opciones: ["Verdadero", "Falso"], respuesta: ok ? 0 : 1, solucion: `${a.territorio}: ${fmt(a.valor)} · ${b.territorio}: ${fmt(b.valor)} (${s.unidad}). Es ${ok ? "verdadero" : "falso"}.`};
