      datos: anual.map(([y, v]) =&gt; [String(y), fmt(v)].concat(refA ? [refA.has(y) ? fmt(refA.get(y)) : "–"] : [])),
      cabecera: ["Año", obj].concat(refA ? ["UE-27"] : []),
