prepararQuien = (datos, pool, n, dificil, azar = Math.random) =&gt; {
  const z = datos.map(d =&gt; { const v = pool.map(c =&gt; d.valores.get(c)).filter(Number.isFinite); return {m: d3.mean(v), s: d3.deviation(v) || 1}; });
